// ═══════════════════════════════════════════════════════════════════════
//  THE COST BOUNDARY — INVERTED.
//
//  Every other watcher in this folder polls something cheap and spends a turn
//  when the answer is YES. Here the cheap half IS the work: the backup node
//  above already snapshotted the database, verified it, uploaded it and pruned
//  the old copies, for zero tokens and no agent.
//
//  So this Gate fires on FAILURE. A successful backup returns no items and the
//  branch stops — which is what happens every night. Orion is woken only when
//  the owner's protection is actually gone.
// ═══════════════════════════════════════════════════════════════════════

const res = $input.first().json || {};
const store = $getWorkflowStaticData('global');

if (res.ok) {
  // Recovered after a run of failures? Say so once, then go quiet again.
  if (store.broken) {
    store.broken = false;
    return [{ json: {
      recovered: true,
      intent: 'The nightly database backup is working again — ' + res.name +
        ' uploaded cleanly. Tell the owner in ONE line. Do not call any tool.'
    }}];
  }
  return [];
}

// EDGE-triggered: a revoked Google token fails identically every night, and a
// push a night would bury the one that mattered. One on the transition.
if (store.broken) return [];
store.broken = true;

const stage = res.stage || 'unknown';
let intent;

if (stage === 'integrity') {
  // Not a backup problem. The snapshot of the LIVE database failed its integrity
  // check, and that is the most serious thing this workflow can discover.
  intent = 'URGENT: the nightly backup snapshot FAILED ITS INTEGRITY CHECK (' +
    (res.error || '') + '). This is a statement about the LIVE DATABASE, not ' +
    'about the backup. Tell the owner immediately and in exactly those terms, ' +
    'say that no backup was uploaded, and recommend he stop writing to it until ' +
    'it is looked at. Do not describe this as a transient error.';
} else if (stage === 'google' || stage === 'disabled') {
  intent = 'The nightly database backup cannot run: ' + (res.error || '') +
    ' This will fail identically every night until it is fixed, so say that ' +
    'rather than implying it might pass tomorrow. Tell the owner in one short ' +
    'message what to do. Do not call any tool.';
} else {
  intent = 'The nightly database backup FAILED at the "' + stage + '" stage: ' +
    (res.error || 'no detail') + '. Tell the owner he is NOT backed up, in that ' +
    'sentence. You may run octavius_protocol(action="backup") ONCE to retry — ' +
    'if it fails again, report both failures and stop.';
}

return [{ json: { stage: stage, error: res.error || '', intent: intent } }];
